import React, { useState, useEffect } from "react";
import TaskList from "./TaskList";
import { getTasksByUser, updateTaskStatus } from "../utils/storage";

const UserDashboard = () => {
  const [tasks, setTasks] = useState([]);
  const [message, setMessage] = useState("");

  useEffect(() => {
    loadTasks();
  }, []);

  const loadTasks = () => {
    // Get current user from localStorage
    const currentUser = JSON.parse(localStorage.getItem("currentUser") || "{}");
    if (currentUser.id) {
      const userTasks = getTasksByUser(currentUser.id);
      setTasks(userTasks);
    }
  };

  const handleTaskStatusUpdate = (taskId, status) => {
    updateTaskStatus(taskId, status);
    setMessage("Task status updated successfully!");
    loadTasks();

    setTimeout(() => setMessage(""), 3000);
  };

  const pendingTasks = tasks.filter((task) => task.status === "Pending");
  const completedTasks = tasks.filter((task) => task.status === "Completed");

  return (
    <div className="user-dashboard">
      {message && (
        <div
          className="message"
          style={{
            background: "#10b981",
            color: "white",
            padding: "15px",
            borderRadius: "5px",
            marginBottom: "20px",
            textAlign: "center",
          }}
        >
          {message}
        </div>
      )}

      <div className="dashboard-card">
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
          }}
        >
          <h2>My Tasks Overview</h2>
          <div style={{ display: "flex", gap: "20px" }}>
            <div style={{ textAlign: "center" }}>
              <div
                style={{
                  fontSize: "24px",
                  fontWeight: "bold",
                  color: "#f59e0b",
                }}
              >
                {pendingTasks.length}
              </div>
              <div style={{ fontSize: "12px", color: "#666" }}>Pending</div>
            </div>
            <div style={{ textAlign: "center" }}>
              <div
                style={{
                  fontSize: "24px",
                  fontWeight: "bold",
                  color: "#10b981",
                }}
              >
                {completedTasks.length}
              </div>
              <div style={{ fontSize: "12px", color: "#666" }}>Completed</div>
            </div>
            <div style={{ textAlign: "center" }}>
              <div
                style={{
                  fontSize: "24px",
                  fontWeight: "bold",
                  color: "#667eea",
                }}
              >
                {tasks.length}
              </div>
              <div style={{ fontSize: "12px", color: "#666" }}>Total</div>
            </div>
          </div>
        </div>
      </div>

      <div className="columns">
        <div>
          <div className="dashboard-card">
            <h2>Pending Tasks ({pendingTasks.length})</h2>
            <TaskList
              tasks={pendingTasks}
              onUpdateStatus={handleTaskStatusUpdate}
            />
          </div>
        </div>

        <div>
          <div className="dashboard-card">
            <h2>Completed Tasks ({completedTasks.length})</h2>
            <TaskList
              tasks={completedTasks}
              onUpdateStatus={handleTaskStatusUpdate}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default UserDashboard;
